class Solution:
    def getCollisionTimes(self, cars: List[List[int]]) -> List[float]:
        n = len(cars)
        crash = [-1.0] * n
        for i in range(n - 2, -1, -1):
            p, s = cars[i]
            for j in range(i + 1, n):
                pj, sj = cars[j]
                if s <= sj:
                    continue
                t = (pj - p) / (s - sj)
                if crash[j] == -1 or t <= crash[j]:
                    crash[i] = t
                    break
        return crash

