        n = len(cars)
        crash = [-1.0] * n
        stack = []
        for i in range(n - 1, -1, -1):
            p, s = cars[i]
            while stack:
                pp, ps, ct = stack[-1]
                if s > ps and (pp - p) / (s - ps) <= ct:
                    break
                stack.pop()
            if stack:
                pp, ps, _ = stack[-1]
                crash[i] = (pp - p) / (s - ps)
            stack.append((p, s, crash[i] if crash[i] != -1 else float('inf')))
        return crash

