class Solution {
public:
    vector<double> getCollisionTimes(vector<vector<int>>& cars) {
        int n = cars.size();
        vector<double> crash(n, -1.0);
        vector<array<double, 3>> st;
        for (int i = n - 1; i >= 0; i--) {
            double p = cars[i][0], s = cars[i][1];
            while (!st.empty()) {
                auto& top = st.back();
                if (s > top[1] && (top[0] - p) / (s - top[1]) <= top[2]) break;
                st.pop_back();
            }
            if (!st.empty())
                crash[i] = (st.back()[0] - p) / (s - st.back()[1]);
            st.push_back({p, s, crash[i] == -1 ? numeric_limits<double>::infinity() : crash[i]});
        }
        return crash;
    }
};

