class Solution {
    public double[] getCollisionTimes(int[][] cars) {
        int n = cars.length;
        double[] crash = new double[n];
        Arrays.fill(crash, -1.0);
        Deque<double[]> st = new ArrayDeque<>();
        for (int i = n - 1; i >= 0; i--) {
            double p = cars[i][0], s = cars[i][1];
            while (!st.isEmpty()) {
                double[] top = st.peekLast();
                if (s > top[1] && (top[0] - p) / (s - top[1]) <= top[2]) break;
                st.pollLast();
            }
            if (!st.isEmpty()) {
                double[] top = st.peekLast();
                crash[i] = (top[0] - p) / (s - top[1]);
            }
            st.addLast(new double[]{p, s, crash[i] == -1 ? Double.POSITIVE_INFINITY : crash[i]});
        }
        return crash;
    }
};

